const LANGUAGE_COURSES=[{"id": "ingles", "title": "Inglês", "kind": "language", "tag": "en-US", "cover": "Hello", "description": "Do básico ao avançado: 24 aulas com leitura, atividades, escrita e quatro provas avaliativas.", "source": "https://learnenglish.britishcouncil.org/grammar", "lessons": [{"id": "course-ingles-1", "title": "Cumprimentos e apresentação", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Use hello para cumprimentar e goodbye para se despedir. I é o pronome eu e se escreve sempre com maiúscula. A forma am acompanha I; my indica posse. Na apresentação, nome e nacionalidade podem aparecer em frases curtas.", "phrase": "Hello! My name is Ana. I am Brazilian.", "reading": "", "meaning": "Olá! Meu nome é Ana. Sou brasileira.", "wrong": "Hello! My name are Ana. I is Brazilian.", "task": "Apresente uma pessoa fictícia em três frases: cumprimento, nome e nacionalidade."}, {"id": "course-ingles-2", "title": "Alfabeto e sons", "module": "1 · Básico", "language": true, "stage": 0, "theory": "O inglês usa 26 letras, mas nomes das letras e sons nas palavras são coisas diferentes. Uma vogal pode representar sons diferentes; não leia palavras inglesas usando automaticamente os sons do português. Soletre com o nome das letras e pratique ouvindo e repetindo trechos curtos.", "phrase": "My name is Ana: A, N, A.", "reading": "", "meaning": "Meu nome é Ana: A, N, A.", "wrong": "My name am Ana: A, N, A.", "task": "Escolha um nome fictício, escreva uma apresentação e soletre o nome em voz alta."}, {"id": "course-ingles-3", "title": "To be: afirmação e negação", "module": "1 · Básico", "language": true, "stage": 0, "theory": "No presente, use I am; he, she e it is; you, we e they are. Para negar, coloque not depois do verbo: is not ou isn't. A concordância depende do sujeito, não da palavra que vem depois.", "phrase": "She is a teacher. They are not students.", "reading": "", "meaning": "Ela é professora. Eles não são estudantes.", "wrong": "She are a teacher. They is not students.", "task": "Descreva duas pessoas fictícias e negue uma informação sobre elas."}, {"id": "course-ingles-4", "title": "Perguntas com to be", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Para perguntar com to be, coloque o verbo antes do sujeito. Are you ready? não leva do. Nas respostas curtas, retome pronome e verbo: Yes, I am. Use what para perguntar o quê e where para onde em perguntas de localização.", "phrase": "Are you ready? Yes, I am.", "reading": "", "meaning": "Você está pronto? Sim, estou.", "wrong": "Do you are ready? Yes, I am.", "task": "Escreva um diálogo com uma pergunta usando are e uma resposta curta."}, {"id": "course-ingles-5", "title": "Artigos, plural e demonstrativos", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Use a antes de som consonantal e an antes de som vocálico: an apple. O critério é o som. This aponta algo singular próximo; these é seu plural. Muitos plurais recebem s, mas existem irregulares como child e children.", "phrase": "This is an apple. These are books.", "reading": "", "meaning": "Isto é uma maçã. Estes são livros.", "wrong": "This is a apple. These is books.", "task": "Nomeie três objetos fictícios usando a ou an e transforme uma frase em plural."}, {"id": "course-ingles-6", "title": "Posse, família e números", "module": "1 · Básico", "language": true, "stage": 0, "theory": "My, your, his, her, its, our e their vêm antes do substantivo. Não confunda his com he's: o segundo pode significar he is. Para idade, use be: I am twenty, e não have. Leia números em situações como idade e quantidade.", "phrase": "My sister is twenty years old.", "reading": "", "meaning": "Minha irmã tem vinte anos.", "wrong": "My sister has twenty years old.", "task": "Crie uma pequena família fictícia e informe relação, nome e idade de duas pessoas."}, {"id": "course-ingles-7", "title": "Rotina no presente simples", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Use presente simples para hábitos. Com he, she e it, o verbo afirmativo geralmente recebe s ou es. Nas negativas, don't ou doesn't é seguido pela forma básica: she doesn't work. Advérbios como usually ajudam a indicar frequência.", "phrase": "She works every day. She doesn't work on Sunday.", "reading": "", "meaning": "Ela trabalha todos os dias. Ela não trabalha no domingo.", "wrong": "She work every day. She doesn't works on Sunday.", "task": "Descreva uma rotina fictícia com duas afirmações e uma negativa."}, {"id": "course-ingles-8", "title": "Situações práticas e preposições", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Can expressa capacidade e também participa de pedidos. Depois de can, use a forma básica sem to. At pode indicar um ponto, como at the station; in indica interior ou áreas, conforme o contexto. Aprenda expressões em frases completas.", "phrase": "Can you help me? I am at the station.", "reading": "", "meaning": "Você pode me ajudar? Estou na estação.", "wrong": "Can you to help me? I am at the station.", "task": "Escreva um pedido de ajuda e diga onde a pessoa está."}, {"id": "course-ingles-9", "title": "Presente contínuo e contraste", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Use am, is ou are mais verbo com ing para ações em andamento e situações temporárias. Compare com o presente simples, que descreve hábitos. Alguns verbos de estado, como know, normalmente não aparecem no contínuo nesse sentido.", "phrase": "I usually study at night, but I am studying now.", "reading": "", "meaning": "Geralmente estudo à noite, mas estou estudando agora.", "wrong": "I usually study at night, but I studying now.", "task": "Contraste um hábito fictício com o que está acontecendo agora."}, {"id": "course-ingles-10", "title": "Passado simples", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Em afirmações passadas, verbos regulares geralmente recebem ed; os irregulares precisam ser aprendidos, como go e went. Perguntas e negativas usam did ou didn't mais forma básica. Yesterday estabelece um período passado concluído.", "phrase": "I went to school yesterday. I didn't go by bus.", "reading": "", "meaning": "Fui à escola ontem. Não fui de ônibus.", "wrong": "I went to school yesterday. I didn't went by bus.", "task": "Conte três acontecimentos fictícios de ontem e negue um deles."}, {"id": "course-ingles-11", "title": "Passado contínuo e narrativa", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Was ou were com ing apresenta uma ação em andamento no passado. Uma ação pontual no passado simples pode interrompê-la. Quando a relação for de simultaneidade, while ajuda a ligar as ações; when pode introduzir o evento pontual.", "phrase": "I was reading when the phone rang.", "reading": "", "meaning": "Eu estava lendo quando o telefone tocou.", "wrong": "I were reading when the phone rang.", "task": "Escreva duas frases narrando uma ação em andamento e um acontecimento que a interrompe."}, {"id": "course-ingles-12", "title": "Futuro e planejamento", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Be going to costuma indicar planos ou previsão com evidência presente. Will pode expressar decisão no momento, promessa e previsão. O presente contínuo também pode indicar combinação futura; escolha a forma a partir da intenção comunicativa.", "phrase": "We are going to travel next month.", "reading": "", "meaning": "Vamos viajar no mês que vem.", "wrong": "We going to travel next month.", "task": "Planeje uma viagem fictícia e acrescente uma decisão tomada no momento com will."}, {"id": "course-ingles-13", "title": "Present perfect e experiência", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Have ou has mais particípio relaciona uma experiência ou situação passada ao presente. Para um período passado encerrado e identificado, como yesterday, normalmente use passado simples. Been e gone podem ter sentidos diferentes conforme o retorno ao local.", "phrase": "I have visited London twice.", "reading": "", "meaning": "Visitei Londres duas vezes até agora.", "wrong": "I has visited London twice.", "task": "Relate uma experiência fictícia com present perfect e um evento datado com passado simples."}, {"id": "course-ingles-14", "title": "Comparações e quantidade", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Adjetivos curtos frequentemente recebem er; muitos longos usam more. Há irregulares como good e better. Use much com incontáveis e many com contáveis plurais. A lot of serve para ambos em muitos contextos.", "phrase": "This book is more interesting than that one.", "reading": "", "meaning": "Este livro é mais interessante que aquele.", "wrong": "This book is interestinger than that one.", "task": "Compare dois objetos ou lugares fictícios e escreva uma frase de quantidade."}, {"id": "course-ingles-15", "title": "Modais e conselhos", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Should costuma dar conselho; must pode indicar obrigação forte; have to expressa necessidade. Mustn't indica proibição, enquanto don't have to indica ausência de obrigação. Essa diferença muda o sentido de regras e instruções.", "phrase": "You don't have to come tomorrow.", "reading": "", "meaning": "Você não precisa vir amanhã.", "wrong": "You doesn't have to come tomorrow.", "task": "Escreva um conselho, uma proibição e algo que não é obrigatório."}, {"id": "course-ingles-16", "title": "Condicionais reais e relativas", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Para uma possibilidade futura, uma estrutura frequente é if com presente e resultado com will. Who pode retomar pessoas e which coisas; that é usado em muitas relativas restritivas. Não acrescente um segundo sujeito desnecessário.", "phrase": "If it rains, we will stay home.", "reading": "", "meaning": "Se chover, ficaremos em casa.", "wrong": "If it will rain, we will stay home.", "task": "Crie uma condição futura e descreva uma pessoa com uma oração relativa."}, {"id": "course-ingles-17", "title": "Hipóteses e condicionais irreais", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Para hipótese presente, uma estrutura comum é if mais passado e would mais forma básica. Para contrafactual passado, use if mais past perfect e would have mais particípio. A forma passada pode marcar distância hipotética, não apenas tempo.", "phrase": "If I had more time, I would study more.", "reading": "", "meaning": "Se eu tivesse mais tempo, estudaria mais.", "wrong": "If I would have more time, I would study more.", "task": "Escreva uma hipótese sobre o presente e outra sobre uma decisão passada fictícia."}, {"id": "course-ingles-18", "title": "Voz passiva e foco", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Na passiva, be recebe tempo e concordância; o verbo principal fica no particípio. Ela permite focalizar o processo ou o objeto afetado. O agente com by pode ser omitido quando não é relevante ou conhecido. Compare efeito e clareza com a voz ativa.", "phrase": "The report was written yesterday.", "reading": "", "meaning": "O relatório foi escrito ontem.", "wrong": "The report was wrote yesterday.", "task": "Reescreva uma ação fictícia na ativa e na passiva e explique a mudança de foco."}, {"id": "course-ingles-19", "title": "Discurso indireto", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Ao relatar fala passada, tempos e expressões de tempo podem mudar conforme o contexto. Uma afirmação ainda verdadeira nem sempre exige recuo de tempo. Em pergunta indireta, use ordem afirmativa, como she asked where I lived.", "phrase": "She said that she was tired.", "reading": "", "meaning": "Ela disse que estava cansada.", "wrong": "She said that she were tired.", "task": "Relate uma fala e uma pergunta fictícias sem usar aspas."}, {"id": "course-ingles-20", "title": "Gerúndio, infinitivo e escolhas lexicais", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Alguns verbos pedem ing, como enjoy; outros, to mais infinitivo, como decide. Em alguns casos a forma muda o significado: stop doing é parar a atividade; stop to do é interromper algo para fazer outra coisa. Aprenda o padrão junto do verbo.", "phrase": "I enjoy reading, but I decided to rest.", "reading": "", "meaning": "Gosto de ler, mas decidi descansar.", "wrong": "I enjoy to read, but I decided resting.", "task": "Crie três frases com enjoy, decide e stop, observando seus complementos."}, {"id": "course-ingles-21", "title": "Ênfase e inversão", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Certas expressões negativas no início da frase exigem inversão de auxiliar e sujeito em registro formal: never have I. Não aplique essa regra a qualquer advérbio. Em condicionais formais, had I known corresponde a if I had known.", "phrase": "Never have I seen such a clear explanation.", "reading": "", "meaning": "Nunca vi uma explicação tão clara.", "wrong": "Never I have seen such a clear explanation.", "task": "Reescreva uma frase com never inicial e compare a ênfase com a ordem comum."}, {"id": "course-ingles-22", "title": "Argumentação e cautela", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Em argumentação, separe afirmação, evidência e limite. May, might, seems e suggests ajudam a evitar certeza sem suporte. However marca contraste; therefore marca consequência. Não são intercambiáveis só porque conectam frases.", "phrase": "The evidence suggests that the plan may work.", "reading": "", "meaning": "As evidências sugerem que o plano pode funcionar.", "wrong": "The evidence suggest that the plan may works.", "task": "Escreva um argumento curto com uma evidência fictícia, uma ressalva e uma conclusão prudente."}, {"id": "course-ingles-23", "title": "E-mail formal e negociação", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Use saudação adequada, objetivo explícito e pedido cortês. Could e would ajudam a suavizar solicitações. Prefira frases diretas a traduções literais do português. Antes de enviar, revise destinatário, anexo e nível de formalidade.", "phrase": "Could you send the revised proposal by Friday?", "reading": "", "meaning": "Você poderia enviar a proposta revisada até sexta-feira?", "wrong": "Could you to send the revised proposal by Friday?", "task": "Redija um e-mail fictício de cinco frases pedindo revisão de um prazo."}, {"id": "course-ingles-24", "title": "Leitura crítica e produção avançada", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Identifique a tese, a evidência, as inferências e os conectivos de um texto. Um resumo preserva as ideias centrais sem copiar frases inteiras. Ao revisar, verifique referência de pronomes, consistência verbal e adequação ao público.", "phrase": "Although the proposal is promising, further research is needed.", "reading": "", "meaning": "Embora a proposta seja promissora, são necessárias mais pesquisas.", "wrong": "Although the proposal is promising, further research are needed.", "task": "Escreva 100 a 150 palavras sobre estudo online, com tese, contra-argumento e conclusão; revise concordância e conectivos."}]}, {"id": "espanhol", "title": "Espanhol", "kind": "language", "tag": "es-ES", "cover": "Hola", "description": "Do básico ao avançado: 24 aulas com leitura, atividades, escrita e quatro provas avaliativas.", "source": "https://www.rae.es/dpd/", "lessons": [{"id": "course-espanhol-1", "title": "Saudações e apresentação", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Hola é um cumprimento; buenos días é usado pela manhã. Me llamo introduz o nome e soy expressa origem ou identidade. Usted é uma forma de tratamento formal em muitos contextos, mas seu uso varia entre regiões.", "phrase": "Hola, me llamo Ana y soy brasileña.", "reading": "", "meaning": "Olá, meu nome é Ana e sou brasileira.", "wrong": "Hola, me llamo Ana y estoy brasileña.", "task": "Apresente uma personagem com nome, origem e saudação."}, {"id": "course-espanhol-2", "title": "Alfabeto e pronúncia", "module": "1 · Básico", "language": true, "stage": 0, "theory": "O espanhol tem ñ como letra própria. H normalmente não representa som, e j tem uma realização diferente da portuguesa. A pronúncia de ll e y varia por região. Compare palavras no áudio, sem presumir que toda grafia parecida soa como em português.", "phrase": "Me llamo Ana. ¿Cómo te llamas?", "reading": "", "meaning": "Meu nome é Ana. Como você se chama?", "wrong": "Me llamo Ana. ¿Cómo te llama tú?", "task": "Soletre um nome fictício e pratique uma pergunta de apresentação."}, {"id": "course-espanhol-3", "title": "Artigos e concordância", "module": "1 · Básico", "language": true, "stage": 0, "theory": "El e la são artigos singulares; los e las são plurais. Substantivos e adjetivos normalmente concordam em gênero e número. Nem toda terminação identifica o gênero: el problema é masculino e la mano é feminino.", "phrase": "La casa es pequeña y los libros son nuevos.", "reading": "", "meaning": "A casa é pequena e os livros são novos.", "wrong": "La casa es pequeño y los libros son nueva.", "task": "Descreva dois objetos no singular e dois no plural."}, {"id": "course-espanhol-4", "title": "Ser, estar e hay", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Ser costuma apresentar identidade e características; estar apresenta estados e localização, com usos específicos que precisam de contexto. Hay indica existência e não varia para plural: hay dos libros. Não escolha o verbo apenas pelo critério permanente ou temporário.", "phrase": "Hay un libro en la mesa. La mesa está aquí.", "reading": "", "meaning": "Há um livro na mesa. A mesa está aqui.", "wrong": "Hay un libro en la mesa. La mesa es aquí.", "task": "Descreva um ambiente usando hay e diga onde está um objeto."}, {"id": "course-espanhol-5", "title": "Pronomes e presente regular", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Os verbos regulares se agrupam em ar, er e ir. Yo hablo, tú hablas e ella habla mostram a mudança de pessoa. O pronome pode ser omitido quando a conjugação e o contexto identificam o sujeito. Ustedes usa formas de terceira pessoa do plural.", "phrase": "Estudiamos español todos los días.", "reading": "", "meaning": "Estudamos espanhol todos os dias.", "wrong": "Nosotros estudian español todos los días.", "task": "Descreva uma rotina fictícia com verbos dos três grupos."}, {"id": "course-espanhol-6", "title": "Presente irregular e rotina", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Verbos frequentes têm irregularidades: tener dá tengo; ir dá voy; hacer dá hago. Alguns alteram a vogal do radical, como querer e quiero. Aprenda forma e uso em frases, em vez de transferir a conjugação portuguesa.", "phrase": "Tengo una clase y voy a la escuela.", "reading": "", "meaning": "Tenho uma aula e vou à escola.", "wrong": "Yo tiene una clase y yo va a la escuela.", "task": "Escreva três frases de rotina com tener, ir e hacer."}, {"id": "course-espanhol-7", "title": "Números, horas e perguntas", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Qué, cómo, cuándo e dónde introduzem perguntas e recebem acento interrogativo. Para uma hora, use es la una; para as demais, son las dos. Perguntas escritas abrem com ¿ e fecham com ?. Quantidades concordam com o contexto.", "phrase": "¿Qué hora es? Son las dos.", "reading": "", "meaning": "Que horas são? São duas horas.", "wrong": "¿Qué hora es? Es las dos.", "task": "Monte um diálogo perguntando horário e lugar de uma aula fictícia."}, {"id": "course-espanhol-8", "title": "Pedidos, comida e viagem", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Quisiera pode tornar um pedido mais cortês. Para indicar destino, use ir a; a mais el contrai em al. Leia uma situação de compra ou viagem pensando em quantidade, preço e confirmação, sem usar dados pessoais reais.", "phrase": "Quisiera un café, por favor. Voy al centro.", "reading": "", "meaning": "Eu gostaria de um café, por favor. Vou ao centro.", "wrong": "Quisiera un café, por favor. Voy a el centro.", "task": "Crie um pedido num café e uma pergunta de direção."}, {"id": "course-espanhol-9", "title": "Reflexivos e hábitos", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Em me levanto, o pronome acompanha a pessoa. Antes de verbo conjugado, use me, te, se, nos, os ou se. A construção pode descrever uma rotina; não acrescente um objeto reflexivo se o verbo e o sentido não pedirem isso.", "phrase": "Me levanto temprano y me preparo para salir.", "reading": "", "meaning": "Levanto cedo e me preparo para sair.", "wrong": "Yo se levanto temprano y me preparo para salir.", "task": "Descreva quatro ações de uma manhã fictícia com dois reflexivos."}, {"id": "course-espanhol-10", "title": "Pretérito perfeito simples", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "O pretérito indefinido narra acontecimentos concluídos: hablé, comí, viví. Há irregulares como fui e tuve. Marcadores como ayer podem delimitar o período. Não use as terminações do português por semelhança gráfica.", "phrase": "Ayer estudié y después fui al mercado.", "reading": "", "meaning": "Ontem estudei e depois fui ao mercado.", "wrong": "Ayer estudiaba y después voy al mercado.", "task": "Conte uma sequência fictícia de três acontecimentos de ontem, todos concluídos."}, {"id": "course-espanhol-11", "title": "Imperfeito e contexto narrativo", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "O imperfecto descreve hábitos, estados e ações em curso no passado: estudiaba, vivía. O indefinido costuma apresentar o evento delimitado. A oposição depende da maneira de apresentar a situação, não apenas de quando ela ocorreu.", "phrase": "Estudiaba cuando sonó el teléfono.", "reading": "", "meaning": "Eu estava estudando quando o telefone tocou.", "wrong": "Estudiaba cuando suena ayer el teléfono.", "task": "Escreva uma cena passada e um evento que a interrompeu."}, {"id": "course-espanhol-12", "title": "Pretérito composto e variação", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Haber no presente mais particípio forma he estudiado e hemos visto. O uso em relação ao indefinido varia regionalmente. Em muitas variedades peninsulares, períodos ligados ao presente favorecem o composto. Não generalize essa preferência a todos os falantes.", "phrase": "Hoy he terminado el trabajo.", "reading": "", "meaning": "Hoje terminei o trabalho.", "wrong": "Hoy soy terminado el trabajo.", "task": "Relate uma experiência com haber e particípio; depois narre um evento passado com data encerrada."}, {"id": "course-espanhol-13", "title": "Futuro e condicional", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Ir a mais infinitivo apresenta planos; o futuro simples também expressa previsões e outros valores. O condicional permite hipóteses e pedidos: podría. Mantenha a estrutura escolhida completa, incluindo a preposição na perífrase.", "phrase": "Mañana voy a estudiar; después descansaré.", "reading": "", "meaning": "Amanhã vou estudar; depois descansarei.", "wrong": "Mañana voy estudiar; después descansaré.", "task": "Apresente dois planos fictícios e um pedido com podría."}, {"id": "course-espanhol-14", "title": "Pronomes de objeto", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Lo e la podem retomar objeto direto; le pode indicar indireto. Quando le ou les precede lo, la, los ou las, transforma-se em se: se lo doy. Existem variações de uso, mas essa combinação não se escreve le lo.", "phrase": "El libro es para Ana: se lo doy mañana.", "reading": "", "meaning": "O livro é para Ana: eu o entrego a ela amanhã.", "wrong": "El libro es para Ana: le lo doy mañana.", "task": "Substitua os objetos de duas frases por pronomes e identifique a quem se referem."}, {"id": "course-espanhol-15", "title": "Comparação, por e para", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Más que estabelece comparação; mejor é o comparativo de bueno. Por pode apresentar causa ou percurso, enquanto para pode apresentar finalidade e destinatário. Essas são funções frequentes, não uma regra única que explique todos os usos.", "phrase": "Estudio para aprender y camino por el parque.", "reading": "", "meaning": "Estudo para aprender e caminho pelo parque.", "wrong": "Estudio por aprender y camino para el parque para indicar percurso interior.", "task": "Escreva duas finalidades com para e uma causa com por."}, {"id": "course-espanhol-16", "title": "Presente do subjuntivo", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Desejo, influência e avaliação podem selecionar subjuntivo em subordinadas com que. Quiero que estudies tem um sujeito diferente para estudar. Quando o sujeito é o mesmo, é comum usar infinitivo: quiero estudiar.", "phrase": "Espero que tengas un buen día.", "reading": "", "meaning": "Espero que você tenha um bom dia.", "wrong": "Espero que tienes un buen día.", "task": "Escreva dois desejos sobre outra pessoa fictícia e um plano seu no infinitivo."}, {"id": "course-espanhol-17", "title": "Imperativo e instruções", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "O imperativo varia com pessoa e polaridade. Para tú, habla e no hables contrastam. Os pronomes costumam unir-se ao imperativo afirmativo e anteceder o negativo: dímelo e no me lo digas. Observe também a acentuação.", "phrase": "Habla despacio y no grites.", "reading": "", "meaning": "Fale devagar e não grite.", "wrong": "Habla despacio y no gritas para dar uma ordem negativa.", "task": "Escreva instruções afirmativas e negativas para uma atividade fictícia."}, {"id": "course-espanhol-18", "title": "Hipóteses com si", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Em hipóteses não realizadas no presente, combine si mais imperfeito do subjuntivo com condicional. Tuviera e tuviese são alternativas usuais nesse contexto. Não use condicional na oração com si para esse padrão hipotético.", "phrase": "Si tuviera tiempo, viajaría más.", "reading": "", "meaning": "Se eu tivesse tempo, viajaria mais.", "wrong": "Si tendría tiempo, viajaría más.", "task": "Crie uma hipótese presente sobre estudo e outra sobre viagem."}, {"id": "course-espanhol-19", "title": "Condições passadas e arrependimento", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Para contrafactual passado, use si mais pluscuamperfecto do subjuntivo e um resultado como habría mais particípio. Primeiro estabeleça o fato não ocorrido; depois apresente a consequência imaginada. A concordância temporal ajuda a evitar ambiguidades.", "phrase": "Si hubiera estudiado, habría aprobado.", "reading": "", "meaning": "Se tivesse estudado, teria sido aprovado.", "wrong": "Si habría estudiado, habría aprobado.", "task": "Relate uma decisão fictícia e imagine um resultado diferente no passado."}, {"id": "course-espanhol-20", "title": "Discurso indireto e concordância", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Ao relatar fala, pronomes, tempos e referências como hoy podem mudar. Um relato no passado pode usar imperfecto para uma ação simultânea. A escolha depende do ponto de vista e de a situação continuar válida.", "phrase": "Dijo que estaba cansada y que volvería después.", "reading": "", "meaning": "Disse que estava cansada e que voltaria depois.", "wrong": "Dijo que estaba cansada y que volveré después, referindo-se à própria falante relatada.", "task": "Transforme duas falas fictícias em relato indireto e indique quem é o sujeito."}, {"id": "course-espanhol-21", "title": "Concessão e contraste", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Aunque pode acompanhar indicativo ao apresentar um fato como assumido e subjuntivo ao não afirmar sua realização. Sin embargo apresenta contraste entre enunciados. A escolha muda o que o falante assume como verdadeiro, não apenas a formalidade.", "phrase": "Aunque llueva, iremos al museo.", "reading": "", "meaning": "Mesmo que chova, iremos ao museu.", "wrong": "Aunque llueva, iremos al museo significa que a chuva já aconteceu ontem.", "task": "Escreva uma concessão sobre uma possibilidade e um contraste com sin embargo."}, {"id": "course-espanhol-22", "title": "Voz passiva e construções com se", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Ser mais particípio forma passiva e o particípio concorda com o sujeito. Em se venden libros, há passiva com se e concordância plural. Não confunda automaticamente essa estrutura com toda ocorrência de se, que tem vários usos.", "phrase": "Se venden libros usados.", "reading": "", "meaning": "Vendem-se livros usados.", "wrong": "Se vende libros usados como passiva com sujeito plural.", "task": "Crie um aviso de serviço com se e reescreva uma ação na passiva com ser."}, {"id": "course-espanhol-23", "title": "Argumentação e registro formal", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Uma argumentação clara apresenta posição, motivo e limite. Por lo tanto sinaliza conclusão; sin embargo sinaliza contraste. Em e-mails formais, mantenha tratamento consistente e formule pedidos claros, sem excesso de traduções literais.", "phrase": "La propuesta es útil; sin embargo, necesita ajustes.", "reading": "", "meaning": "A proposta é útil; no entanto, precisa de ajustes.", "wrong": "La propuesta es útil; sin embargo significa por isso, sem contraste.", "task": "Escreva um e-mail de cinco frases propondo uma melhoria e reconhecendo uma limitação."}, {"id": "course-espanhol-24", "title": "Leitura e produção avançada", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Ao ler um texto, distinga tese, exemplos e pressupostos. Um resumo não deve adicionar opinião não atribuída ao autor. Revise tempos, pronomes, acentos e conectivos e adapte o registro a quem receberá o texto.", "phrase": "Conviene considerar otras opciones antes de decidir.", "reading": "", "meaning": "Convém considerar outras opções antes de decidir.", "wrong": "Conviene considerar otras opciones después significa antes de decidir.", "task": "Escreva 100 a 150 palavras defendendo uma forma de estudar; inclua contra-argumento e conclusão."}]}, {"id": "italiano", "title": "Italiano", "kind": "language", "tag": "it-IT", "cover": "Ciao", "description": "Do básico ao avançado: 24 aulas com leitura, atividades, escrita e quatro provas avaliativas.", "source": "https://www.treccani.it/enciclopedia/elenco-opere/La_grammatica_italiana", "lessons": [{"id": "course-italiano-1", "title": "Saudações e apresentação", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Ciao serve em situações informais; buongiorno é adequado em muitos encontros formais. Mi chiamo introduz o nome e sono apresenta identidade ou origem. O tratamento Lei usa terceira pessoa e não deve ser confundido com tu.", "phrase": "Buongiorno, mi chiamo Anna e sono brasiliana.", "reading": "", "meaning": "Bom dia, meu nome é Anna e sou brasileira.", "wrong": "Buongiorno, mi chiamo Anna e è brasiliana.", "task": "Apresente uma personagem fictícia de maneira formal e depois informal."}, {"id": "course-italiano-2", "title": "Alfabeto e pronúncia", "module": "1 · Básico", "language": true, "stage": 0, "theory": "O alfabeto italiano tradicional tem 21 letras; outras aparecem em empréstimos e nomes. C e g mudam de som conforme a vogal seguinte; ch e gh preservam sons duros diante de e e i. Consoantes duplas podem distinguir palavras e precisam de atenção no áudio.", "phrase": "Mi chiamo Chiara.", "reading": "", "meaning": "Meu nome é Chiara.", "wrong": "Io si chiamo Chiara.", "task": "Soletre um nome e liste duas palavras com ch para praticar ouvindo um modelo."}, {"id": "course-italiano-3", "title": "Artigos definidos", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Il, lo e l' são artigos masculinos singulares com contextos diferentes. Lo aparece antes de grupos como s mais consoante e z; il é frequente antes de outras consoantes. La é feminino e l' aparece antes de vogal. No plural, observe i, gli e le.", "phrase": "Lo studente legge il libro.", "reading": "", "meaning": "O estudante lê o livro.", "wrong": "Il studente legge il libro.", "task": "Combine studente, libro e casa com artigos adequados e passe ao plural."}, {"id": "course-italiano-4", "title": "Gênero, plural e adjetivos", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Muitos substantivos em o passam a i; muitos em a passam a e. Terminações em e frequentemente passam a i e podem ser masculinas ou femininas. Adjetivos concordam em gênero e número, com padrões próprios conforme a terminação.", "phrase": "Le case sono piccole e i libri sono nuovi.", "reading": "", "meaning": "As casas são pequenas e os livros são novos.", "wrong": "Le case sono piccolo e i libri sono nuova.", "task": "Descreva quatro objetos fictícios, incluindo singular e plural."}, {"id": "course-italiano-5", "title": "Essere e avere", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Essere no presente dá sono, sei, è, siamo, siete, sono. Avere dá ho, hai, ha, abbiamo, avete, hanno. Idade e certas sensações usam avere: ho vent'anni e ho fame. Não substitua automaticamente por essere a partir do português.", "phrase": "Ho vent'anni e sono studente.", "reading": "", "meaning": "Tenho vinte anos e sou estudante.", "wrong": "Sono vent'anni e ho studente.", "task": "Informe idade e ocupação fictícias e formule uma pergunta com avere."}, {"id": "course-italiano-6", "title": "Presente regular", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Verbos se agrupam em are, ere e ire. Parlare dá parlo, parli, parla; leggere dá leggo, leggi, legge. Alguns verbos em ire inserem isc em certas pessoas, como capisco. Aprenda a família e verifique irregularidades de verbos frequentes.", "phrase": "Parliamo italiano e leggiamo un libro.", "reading": "", "meaning": "Falamos italiano e lemos um livro.", "wrong": "Noi parla italiano e legge un libro.", "task": "Escreva uma rotina de três frases usando verbos dos três grupos."}, {"id": "course-italiano-7", "title": "Perguntas, números e horas", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Dove, quando, come e quanto ajudam a pedir informação. Para horas, è l'una contrasta com sono le due. A pergunta geralmente usa a ordem comum com entonação interrogativa; a escrita fecha com ponto de interrogação.", "phrase": "Che ore sono? Sono le tre.", "reading": "", "meaning": "Que horas são? São três horas.", "wrong": "Che ore sono? È le tre.", "task": "Crie um diálogo perguntando horário, preço e localização de uma aula fictícia."}, {"id": "course-italiano-8", "title": "Pedidos e preposições", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Vorrei é uma forma cortês de pedir. Algumas preposições se unem ao artigo: a mais il dá al; di mais il dá del. Para destino, observe expressões como vado a Roma e vado in Italia. Aprenda combinações em contexto.", "phrase": "Vorrei un caffè, per favore. Vado al centro.", "reading": "", "meaning": "Eu gostaria de um café, por favor. Vou ao centro.", "wrong": "Vorrei un caffè, per favore. Vado a il centro.", "task": "Faça um pedido num café e diga dois destinos fictícios."}, {"id": "course-italiano-9", "title": "Reflexivos e rotina", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Mi alzo descreve uma ação associada ao próprio sujeito. Os pronomes variam: mi, ti, si, ci, vi, si. No infinitivo, o pronome pode se unir ao verbo. Não use a mesma forma pronominal para todas as pessoas.", "phrase": "Mi alzo presto e mi preparo.", "reading": "", "meaning": "Levanto cedo e me preparo.", "wrong": "Io si alzo presto e mi preparo.", "task": "Descreva uma manhã fictícia com quatro ações, incluindo dois reflexivos."}, {"id": "course-italiano-10", "title": "Passato prossimo com avere", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "O passato prossimo une auxiliar no presente e particípio passado. Muitos verbos transitivos usam avere: ho letto. Verbos regulares frequentemente têm particípios em ato, uto e ito, mas os irregulares precisam de estudo. Ele apresenta acontecimentos passados em muitos contextos.", "phrase": "Ieri ho letto un libro.", "reading": "", "meaning": "Ontem li um livro.", "wrong": "Ieri ho leggere un libro.", "task": "Conte três atividades fictícias de ontem usando avere e particípio."}, {"id": "course-italiano-11", "title": "Passato prossimo com essere", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Alguns verbos usam essere no composto, incluindo andare e vários reflexivos. Com essere, o particípio concorda com o sujeito: Maria è andata. Não suponha que qualquer verbo de movimento tenha o mesmo auxiliar; consulte o uso do verbo.", "phrase": "Maria è andata a scuola.", "reading": "", "meaning": "Maria foi à escola.", "wrong": "Maria è andato a scuola.", "task": "Relate o deslocamento de duas personagens e confira a concordância do particípio."}, {"id": "course-italiano-12", "title": "Imperfetto e narrativa", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "O imperfetto apresenta hábitos, descrições e ações em curso no passado. O passato prossimo costuma avançar a narrativa com eventos delimitados. A escolha depende do ponto de vista: compare o cenário ao acontecimento principal.", "phrase": "Leggevo quando è arrivato Marco.", "reading": "", "meaning": "Eu estava lendo quando Marco chegou.", "wrong": "Leggevo quando Marco arrivare ieri.", "task": "Escreva uma cena passada seguida de um acontecimento que a interrompeu."}, {"id": "course-italiano-13", "title": "Futuro e planejamento", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "O futuro simples apresenta previsões e eventos futuros, entre outros valores. Andare tem andrò e essere tem sarò. O presente com indicação temporal também pode falar de planos; escolha uma forma coerente com a situação e mantenha a concordância.", "phrase": "Domani studierò e poi uscirò.", "reading": "", "meaning": "Amanhã estudarei e depois sairei.", "wrong": "Domani io studierà e poi uscirò.", "task": "Planeje um dia fictício com três ações no futuro."}, {"id": "course-italiano-14", "title": "Pronomes diretos e indiretos", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Lo e la retomam objetos diretos singulares; gli e le podem indicar destinatários em usos específicos. Os pronomes vêm normalmente antes do verbo conjugado. Em compostos, há regras de concordância com certos pronomes diretos que merecem atenção.", "phrase": "Vedo Anna e la saluto.", "reading": "", "meaning": "Vejo Anna e a cumprimento.", "wrong": "Vedo Anna e lo saluto, retomando Anna.", "task": "Substitua dois objetos por pronomes e diga a quem cada pronome se refere."}, {"id": "course-italiano-15", "title": "Ci, ne e quantidades", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Ci pode retomar um lugar e ne pode retomar uma quantidade ou um complemento introduzido por di. A função depende da frase, por isso traduções isoladas não bastam. Em ne voglio due, o objeto já foi estabelecido no contexto.", "phrase": "Quanti libri vuoi? Ne voglio due.", "reading": "", "meaning": "Quantos livros você quer? Quero dois deles.", "wrong": "Quanti libri vuoi? Ci voglio due, retomando a quantidade de livros.", "task": "Crie um diálogo de quantidade com ne e uma referência de lugar com ci."}, {"id": "course-italiano-16", "title": "Comparação e conectivos", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Più e meno com di ou che participam de comparações conforme os termos relacionados. Migliore é uma forma comparativa de buono. Perché pode apresentar causa ou pergunta; però introduz contraste. Observe o papel do conectivo na relação entre ideias.", "phrase": "Questo libro è più interessante di quello.", "reading": "", "meaning": "Este livro é mais interessante que aquele.", "wrong": "Questo libro è più interessante da quello.", "task": "Compare dois materiais fictícios e acrescente uma justificativa e um contraste."}, {"id": "course-italiano-17", "title": "Condizionale e cortesia", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "O condizionale presente aparece em pedidos, desejos e possibilidades. Vorrei é de volere; potrei é de potere. Esse modo ajuda a suavizar pedidos, mas a cortesia também depende do contexto, da saudação e do tratamento escolhido.", "phrase": "Potrebbe aiutarmi, per favore?", "reading": "", "meaning": "O senhor ou a senhora poderia me ajudar, por favor?", "wrong": "Potrebbe aiutare io, per favore?", "task": "Escreva um pedido formal e um desejo pessoal com condizionale."}, {"id": "course-italiano-18", "title": "Congiuntivo presente", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Certas construções de opinião, desejo ou necessidade selecionam congiuntivo em subordinadas com che. Penso che sia distingue-se de uma afirmação direta com è. Não use o modo apenas por haver che; a construção e o sentido precisam ser considerados.", "phrase": "Penso che sia una buona idea.", "reading": "", "meaning": "Acho que seja uma boa ideia.", "wrong": "Penso che essere una buona idea.", "task": "Formule uma opinião e um desejo sobre pessoas fictícias usando congiuntivo."}, {"id": "course-italiano-19", "title": "Hipóteses e congiuntivo imperfetto", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Uma hipótese não realizada no presente pode usar se mais congiuntivo imperfetto e resultado no condizionale. Avessi e avrei exercem funções diferentes nesse padrão. Evite usar condizionale na oração condicional de uma hipótese irreal.", "phrase": "Se avessi tempo, viaggerei di più.", "reading": "", "meaning": "Se eu tivesse tempo, viajaria mais.", "wrong": "Se avrei tempo, viaggerei di più.", "task": "Crie duas hipóteses sobre estudo e viagem, conferindo o verbo depois de se."}, {"id": "course-italiano-20", "title": "Hipóteses passadas e sequência temporal", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Para imaginar outra consequência de um passado não ocorrido, combine congiuntivo trapassato e condizionale passato. O auxiliar e o particípio formam cada tempo composto. A concordância com essere continua importante.", "phrase": "Se avessi studiato, avrei superato l'esame.", "reading": "", "meaning": "Se tivesse estudado, teria passado na prova.", "wrong": "Se avrei studiato, avrei superato l'esame.", "task": "Relate uma situação fictícia e formule uma alternativa contrafactual no passado."}, {"id": "course-italiano-21", "title": "Passiva e registro escrito", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "A passiva com essere mais particípio focaliza o elemento afetado e o particípio concorda com ele. Outras construções, como a passiva com venire em tempos simples, têm restrições próprias. Identifique o agente e decida se ele precisa aparecer.", "phrase": "La lettera è stata scritta ieri.", "reading": "", "meaning": "A carta foi escrita ontem.", "wrong": "La lettera è stato scritto ieri.", "task": "Transforme duas frases fictícias da ativa para a passiva e explique a mudança de foco."}, {"id": "course-italiano-22", "title": "Relativas e discurso indireto", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Che é invariável em muitas relativas; cui aparece com preposição quando a função exige. No discurso indireto, ajuste pessoas e tempos ao ponto de vista do relato. Não traduza automaticamente que por uma única forma em todos os contextos.", "phrase": "La persona con cui lavoro è gentile.", "reading": "", "meaning": "A pessoa com quem trabalho é gentil.", "wrong": "La persona con che lavoro è gentile.", "task": "Descreva uma pessoa com uma relativa e depois relate uma fala fictícia."}, {"id": "course-italiano-23", "title": "Concessão e argumentação formal", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Sebbene costuma selecionar congiuntivo; tuttavia marca contraste entre ideias. Uma argumentação precisa apresentar posição, motivo e limite. Escolha o registro conforme o público e mantenha o tratamento formal consistente em mensagens profissionais.", "phrase": "Sebbene sia difficile, vale la pena provare.", "reading": "", "meaning": "Embora seja difícil, vale a pena tentar.", "wrong": "Sebbene essere difficile, vale la pena provare.", "task": "Escreva cinco frases defendendo uma proposta e reconhecendo uma dificuldade."}, {"id": "course-italiano-24", "title": "Leitura crítica e produção avançada", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Leia buscando tese, razões e implicações, sem se apoiar somente em palavras parecidas com português. No resumo, preserve a posição do autor e indique o que é opinião sua. Revise auxiliares, concordância e relações entre frases antes de concluir.", "phrase": "In conclusione, occorre valutare sia i vantaggi sia i limiti.", "reading": "", "meaning": "Em conclusão, é preciso avaliar tanto as vantagens quanto os limites.", "wrong": "In conclusione, occorre valutare significa que nenhuma avaliação é necessária.", "task": "Escreva 100 a 150 palavras sobre aprendizagem online, com argumento, ressalva e conclusão."}]}, {"id": "japones", "title": "Japonês", "kind": "language", "tag": "ja-JP", "cover": "こんにちは", "description": "Do básico ao avançado: 24 aulas com leitura, atividades, escrita e quatro provas avaliativas.", "source": "https://www.irodori.jpf.go.jp/en/resources.html", "lessons": [{"id": "course-japones-1", "title": "Sistemas de escrita e cumprimento", "module": "1 · Básico", "language": true, "stage": 0, "theory": "O japonês combina hiragana, katakana e kanji. Hiragana representa unidades sonoras e terminações; katakana aparece em muitos empréstimos; kanji relaciona forma e significado com leituras dependentes da palavra. Comece pelos kana e use a romanização apenas como apoio inicial.", "phrase": "こんにちは。はじめまして。", "reading": "Konnichiwa. Hajimemashite.", "meaning": "Olá. Prazer em conhecê-lo.", "wrong": "こんにちは significa boa noite exclusivamente.", "task": "Copie a frase em kana e apresente oralmente um cumprimento; observe que は em こんにちは é pronunciado wa."}, {"id": "course-japones-2", "title": "Hiragana e ritmo", "module": "1 · Básico", "language": true, "stage": 0, "theory": "As vogais básicas são あ い う え お. O ritmo japonês se organiza em moras: vogais longas, ん e o pequeno っ influenciam a duração. Não use a sílaba portuguesa como única medida de ritmo. Pratique ouvir e escrever sem acelerar.", "phrase": "あ、い、う、え、お。", "reading": "A, i, u, e, o.", "meaning": "A sequência apresenta as cinco vogais básicas do hiragana.", "wrong": "あ、い、う、え、お representam os números de um a cinco.", "task": "Escreva as cinco vogais e pratique distingui-las ouvindo um modelo nativo."}, {"id": "course-japones-3", "title": "Katakana e palavras emprestadas", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Katakana representa muitos nomes estrangeiros e empréstimos. O traço ー costuma prolongar a vogal anterior. Não leia empréstimos como se mantivessem exatamente a pronúncia da língua de origem. Compare コ e ロ e outras formas visualmente próximas.", "phrase": "コーヒーをください。", "reading": "Kōhī o kudasai.", "meaning": "Um café, por favor.", "wrong": "コーヒーをください significa não quero café.", "task": "Copie コーヒー e crie uma pequena lista de três empréstimos consultando uma referência."}, {"id": "course-japones-4", "title": "Apresentação: は e です", "module": "1 · Básico", "language": true, "stage": 0, "theory": "は marca um tópico e nessa função se lê wa. です participa de afirmações nominais polidas; não é uma tradução universal de ser ou estar. A ordem frequentemente coloca o predicado no fim. Informações recuperáveis pelo contexto podem ser omitidas.", "phrase": "私は学生です。", "reading": "Watashi wa gakusei desu.", "meaning": "Sou estudante.", "wrong": "私は学生です significa eu era professor ontem.", "task": "Apresente uma personagem substituindo 学生 por outra identidade que você tenha estudado."}, {"id": "course-japones-5", "title": "Perguntas, negação e posse", "module": "1 · Básico", "language": true, "stage": 0, "theory": "か ao final pode marcar pergunta em registro polido. ではありません ou じゃありません nega uma identificação nominal nesse registro. の liga nomes em relações como posse ou associação; o possuidor antecede o elemento relacionado.", "phrase": "これは私の本ですか。", "reading": "Kore wa watashi no hon desu ka.", "meaning": "Este é o meu livro?", "wrong": "これは私の本ですか significa este não é um livro, sem pergunta.", "task": "Escreva uma pergunta sobre um objeto e uma resposta negativa polida."}, {"id": "course-japones-6", "title": "Demonstrativos e localização", "module": "1 · Básico", "language": true, "stage": 0, "theory": "これ aponta algo próximo do falante; それ, do interlocutor ou do contexto; あれ, distante. ここ, そこ e あそこ referem-se a lugares. どこ pergunta localização. Aprenda os conjuntos em situações, sem reduzir toda escolha a distância física.", "phrase": "トイレはどこですか。", "reading": "Toire wa doko desu ka.", "meaning": "Onde fica o banheiro?", "wrong": "トイレはどこですか significa quanto custa o banheiro.", "task": "Crie um diálogo perguntando a localização de dois lugares fictícios."}, {"id": "course-japones-7", "title": "Verbos polidos e partículas", "module": "1 · Básico", "language": true, "stage": 0, "theory": "A forma ます é frequente no registro polido não passado; ません nega. を marca objeto direto e nessa função se lê o. に e へ podem marcar destino com verbos de movimento; で pode marcar onde uma ação ocorre. Não troque as partículas só pela tradução portuguesa.", "phrase": "学校で日本語を勉強します。", "reading": "Gakkō de Nihongo o benkyō shimasu.", "meaning": "Estudo japonês na escola.", "wrong": "学校で日本語を勉強します significa vou da escola ao Japão.", "task": "Escreva onde uma pessoa fictícia estuda e o que ela estuda, usando で e を."}, {"id": "course-japones-8", "title": "Números, tempo e existência", "module": "1 · Básico", "language": true, "stage": 0, "theory": "一, 二 e 三 representam um, dois e três. Contagem pode exigir classificadores e mudanças de leitura. あります é usado em muitos casos de existência de coisas e います, de seres animados. Para horário, pratique expressões completas em vez de combinar números mecanicamente.", "phrase": "部屋に猫がいます。", "reading": "Heya ni neko ga imasu.", "meaning": "Há um gato no quarto.", "wrong": "部屋に猫があります é a forma usual para um gato vivo nesse contexto.", "task": "Descreva dois elementos numa sala fictícia, diferenciando existência animada e inanimada."}, {"id": "course-japones-9", "title": "Adjetivos e passado", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Adjetivos em い formam, em muitos casos, passado com かった: 高い vira 高かった. Adjetivos do grupo な usam construções como 静かでした. いい tem formas irregulares como よかった. Nem toda palavra terminada em i pertence ao primeiro grupo.", "phrase": "昨日は寒かったです。", "reading": "Kinō wa samukatta desu.", "meaning": "Ontem fez frio.", "wrong": "昨日は寒いでしたです。", "task": "Descreva o clima de ontem e um lugar tranquilo no passado."}, {"id": "course-japones-10", "title": "Forma de dicionário e grupos verbais", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "A forma de dicionário é central para diversas construções. Os verbos se distribuem em grupos com padrões distintos e há irregulares como する e 来る. 食べます corresponde a 食べる; 書きます a 書く. Não remova ます da mesma forma em todos os verbos.", "phrase": "毎日本を読む。", "reading": "Mainichi hon o yomu.", "meaning": "Leio livros todos os dias, em estilo simples.", "wrong": "毎日本を読む significa nunca li livro algum.", "task": "Compare duas frases em estilo polido e simples, mantendo o sentido e o público consistentes."}, {"id": "course-japones-11", "title": "Forma て e pedidos", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "A forma て se combina com construções como ください para pedidos. Sua formação varia conforme o grupo: 読む dá 読んで e 書く dá 書いて. Ela também liga ações; não é um tempo verbal isolado equivalente a um único tempo português.", "phrase": "ゆっくり話してください。", "reading": "Yukkuri hanashite kudasai.", "meaning": "Fale devagar, por favor.", "wrong": "ゆっくり話してください significa não fale devagar.", "task": "Escreva dois pedidos corteses usando a forma て."}, {"id": "course-japones-12", "title": "Forma ている e aspecto", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "ている pode apresentar atividade em curso e também estado resultante, dependendo do verbo. Compare ler agora com morar em um lugar. Não traduza todas as ocorrências por estar fazendo: a combinação e o contexto determinam o sentido.", "phrase": "今、本を読んでいます。", "reading": "Ima, hon o yonde imasu.", "meaning": "Estou lendo um livro agora.", "wrong": "今、本を読んでいます significa lerei um livro amanhã, sem ação atual.", "task": "Descreva uma ação em curso e observe uma expressão de estado com ている numa referência."}, {"id": "course-japones-13", "title": "Forma た e experiências", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "A forma た é usada no passado simples e em construções como たことがある para experiência. 行ったことがあります indica ter ido alguma vez. A referência temporal e o foco distinguem experiência de um evento específico com data.", "phrase": "日本に行ったことがあります。", "reading": "Nihon ni itta koto ga arimasu.", "meaning": "Já fui ao Japão alguma vez.", "wrong": "日本に行ったことがあります significa nunca fui ao Japão.", "task": "Escreva uma experiência fictícia e contraste com uma visita em data específica."}, {"id": "course-japones-14", "title": "Negação simples e obrigação", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "A forma ない varia por grupo verbal: 行く dá 行かない; 食べる dá 食べない. ないでください pede que não se faça algo. Construções como なければなりません expressam necessidade; seu registro e força dependem do contexto.", "phrase": "ここで写真を撮らないでください。", "reading": "Koko de shashin o toranaide kudasai.", "meaning": "Não tire fotos aqui, por favor.", "wrong": "ここで写真を撮らないでください significa tire muitas fotos aqui.", "task": "Crie um aviso negativo e uma frase de obrigação para um local fictício."}, {"id": "course-japones-15", "title": "Desejo e potencial", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "A forma たい expressa desejo de realizar uma ação e se flexiona de maneira semelhante a um adjetivo em い. Formas potenciais expressam capacidade ou possibilidade; 食べられる pode ser potencial conforme o contexto. Não confunda querer com poder.", "phrase": "日本語をもっと勉強したいです。", "reading": "Nihongo o motto benkyō shitai desu.", "meaning": "Quero estudar mais japonês.", "wrong": "日本語をもっと勉強したいです significa sou obrigado a estudar menos japonês.", "task": "Escreva um desejo e uma capacidade de uma personagem fictícia."}, {"id": "course-japones-16", "title": "Comparação e orações relativas", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "より pode estabelecer a referência da comparação; ほう pode destacar uma alternativa. Orações que modificam um nome vêm antes dele, sem um pronome relativo equivalente a que em português. Identifique primeiro o nome que recebe a descrição.", "phrase": "昨日買った本を読みます。", "reading": "Kinō katta hon o yomimasu.", "meaning": "Vou ler o livro que comprei ontem.", "wrong": "昨日買った本を読みます significa comprei amanhã o livro que li ontem.", "task": "Descreva um livro ou objeto com uma oração anterior ao substantivo."}, {"id": "course-japones-17", "title": "Condições: と, ば, たら e なら", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "As formas condicionais têm usos que se sobrepõem, mas não são totalmente intercambiáveis. と é frequente em resultados regulares; たら pode indicar condição ou sequência após realização; なら toma uma hipótese como ponto de partida. Observe restrições e contexto em cada exemplo.", "phrase": "時間があったら、勉強します。", "reading": "Jikan ga attara, benkyō shimasu.", "meaning": "Se tiver tempo, estudarei.", "wrong": "時間があったら、勉強します significa que estudar é impossível mesmo com tempo.", "task": "Formule uma condição com たら e descreva em português qual é a hipótese e qual é o resultado."}, {"id": "course-japones-18", "title": "Passiva e perspectiva", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "A passiva altera a perspectiva sobre quem sofre ou recebe uma ação. Sua formação varia por grupo: 褒める dá 褒められる. Algumas formas coincidem com o potencial; o contexto distingue. Há usos de passiva que expressam efeito sobre a pessoa, não apenas tradução literal.", "phrase": "私は先生に褒められました。", "reading": "Watashi wa sensei ni homeraremashita.", "meaning": "Fui elogiado pelo professor.", "wrong": "私は先生に褒められました significa elogiei o professor, com o mesmo foco.", "task": "Compare uma ação ativa e passiva e identifique agente e pessoa afetada."}, {"id": "course-japones-19", "title": "Causativa e permissão", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "A causativa pode indicar fazer alguém agir ou permitir que aja, conforme o contexto. 食べる dá 食べさせる e 行く dá 行かせる. A relação entre participantes e as partículas precisam ser estudadas junto do verbo; não trate a forma como ordem obrigatória em todo uso.", "phrase": "先生は学生に作文を書かせました。", "reading": "Sensei wa gakusei ni sakubun o kakasemashita.", "meaning": "O professor fez os alunos escreverem uma redação.", "wrong": "先生は学生に作文を書かせました significa os alunos fizeram o professor escrever.", "task": "Explique quem orienta a ação e quem escreve; depois crie um exemplo simples."}, {"id": "course-japones-20", "title": "Linguagem honorífica e humilde", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Keigo depende da relação entre falante, interlocutor e pessoa mencionada. いらっしゃる pode elevar ações como ir, vir e estar; 伺う pode reduzir a posição do próprio grupo em contextos adequados. Polidez não é apenas trocar a terminação: a escolha lexical importa.", "phrase": "明日、先生がいらっしゃいます。", "reading": "Ashita, sensei ga irasshaimasu.", "meaning": "O professor virá amanhã, em linguagem respeitosa.", "wrong": "明日、先生がいらっしゃいます é linguagem humilde para reduzir o próprio professor.", "task": "Compare uma referência respeitosa a outra pessoa com uma forma humilde para sua própria ação fictícia."}, {"id": "course-japones-21", "title": "Explicação, inferência e fonte", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "のです pode apresentar explicação ligada ao contexto. そうです tem construções distintas para aparência e relato: おいしそうです e おいしいそうです não têm a mesma estrutura. Indique se você observou, inferiu ou recebeu a informação de alguém.", "phrase": "天気予報によると、明日は雨だそうです。", "reading": "Tenki yohō ni yoru to, ashita wa ame da sō desu.", "meaning": "Segundo a previsão, amanhã choverá.", "wrong": "天気予報によると、明日は雨だそうです afirma que o falante viu a chuva de amanhã pessoalmente.", "task": "Relate uma informação fictícia e identifique a fonte, sem apresentá-la como observação direta."}, {"id": "course-japones-22", "title": "Concessão e conectivos escritos", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "ても pode expressar concessão; しかし marca contraste entre ideias. したがって introduz consequência em registros escritos. Conectivos devem refletir a relação lógica, não apenas variar o vocabulário. Mantenha o estilo simples ou polido consistente dentro do texto.", "phrase": "難しくても、続けます。", "reading": "Muzukashikute mo, tsuzukemasu.", "meaning": "Mesmo sendo difícil, continuarei.", "wrong": "難しくても、続けます significa só continuarei se for fácil.", "task": "Escreva duas frases ligando dificuldade e decisão com uma concessão."}, {"id": "course-japones-23", "title": "Leitura e coesão avançada", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Em textos japoneses, sujeitos podem ser omitidos e retomados pelo contexto. Localize o predicado final e as orações que modificam nomes antes de traduzir. Diferencie posição do autor de informação atribuída a terceiros. Em escrita formal, consistência entre estilos é importante.", "phrase": "この方法には利点がある一方で、課題も残っている。", "reading": "Kono hōhō ni wa riten ga aru ippō de, kadai mo nokotte iru.", "meaning": "Este método tem vantagens, mas ainda há desafios.", "wrong": "この方法には利点がある一方で、課題も残っている significa que o método não tem nenhum desafio.", "task": "Escreva um pequeno parágrafo com uma vantagem, um limite e uma conclusão sobre uma forma de estudar; use uma referência para revisar."}, {"id": "course-japones-24", "title": "Produção e revisão de texto", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Planeje uma mensagem pelo propósito e pelo destinatário. Escreva em frases que você consegue explicar, confira partículas e formas verbais e reduza o apoio da romanização. Reconhecer uma estrutura avançada não substitui prática de leitura e interação em diferentes contextos.", "phrase": "まず資料を読み、その後で意見をまとめます。", "reading": "Mazu shiryō o yomi, sono ato de iken o matomemasu.", "meaning": "Primeiro leio o material e depois organizo minha opinião.", "wrong": "まず資料を読み、その後で意見をまとめます significa que a opinião foi organizada antes da leitura, nessa ordem expressa.", "task": "Produza de cinco a oito frases sobre um plano de estudo e revise ordem, partículas, coerência e registro."}]}, {"id": "chines", "title": "Chinês — Mandarim", "kind": "language", "tag": "zh-CN", "cover": "你好", "description": "Do básico ao avançado: 24 aulas com leitura, atividades, escrita e quatro provas avaliativas.", "source": "https://www.cheng-tsui.com/resources", "lessons": [{"id": "course-chines-1", "title": "Pinyin, tons e primeiro contato", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Este curso usa mandarim e caracteres simplificados. Pinyin representa a pronúncia com letras latinas e marcas tonais; não deve ser lido como português. Os quatro tons plenos e o tom neutro influenciam o significado. Comece ouvindo, imitando e comparando palavras curtas.", "phrase": "你好！", "reading": "Nǐ hǎo!", "meaning": "Olá!", "wrong": "你好 significa adeus exclusivamente.", "task": "Copie 你好 e pratique o cumprimento com um modelo de áudio; observe que dois terceiros tons seguidos alteram a realização do primeiro."}, {"id": "course-chines-2", "title": "Caracteres e ordem de escrita", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Caracteres não funcionam como letras de um alfabeto. Componentes podem ajudar a memorizar significado ou som, mas não garantem uma única leitura. Pratique traços e ordem com referência confiável; a romanização serve de apoio e deve ser gradualmente reduzida.", "phrase": "我是学生。", "reading": "Wǒ shì xuésheng.", "meaning": "Sou estudante.", "wrong": "我是学生 significa sou professor.", "task": "Copie 我, 是 e 学生; associe cada palavra à frase e explique seu papel."}, {"id": "course-chines-3", "title": "Apresentação com 是", "module": "1 · Básico", "language": true, "stage": 0, "theory": "A ordem básica frequentemente é sujeito, verbo e objeto. 是 liga identificações nominais, como profissão ou nacionalidade. 不 costuma negar 是. Não coloque 是 automaticamente antes de todo adjetivo; predicados adjetivais têm estruturas próprias.", "phrase": "我不是老师，我是学生。", "reading": "Wǒ bú shì lǎoshī, wǒ shì xuésheng.", "meaning": "Não sou professor; sou estudante.", "wrong": "我不是老师，我是学生 significa sou professor e não sou estudante.", "task": "Apresente uma personagem e negue uma identificação incorreta."}, {"id": "course-chines-4", "title": "Perguntas com 吗 e palavras interrogativas", "module": "1 · Básico", "language": true, "stage": 0, "theory": "吗 transforma muitas afirmações em perguntas de sim ou não. Palavras como 谁 e 什么 ficam normalmente na posição da informação pedida. Uma pergunta com 什么 não precisa receber 吗 como se isso fosse uma regra universal. O padrão depende da construção.", "phrase": "你叫什么名字？", "reading": "Nǐ jiào shénme míngzi?", "meaning": "Como você se chama?", "wrong": "你叫什么名字？ pergunta quantos anos você tem.", "task": "Crie um diálogo perguntando nome e confirmando uma informação com 吗."}, {"id": "course-chines-5", "title": "Números e classificadores", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Depois de número ou demonstrativo, muitos substantivos exigem classificador: 一个学生. 个 é frequente, mas não serve para todo contexto. Para livros, 本 é comum. 两 frequentemente aparece antes de classificadores para dois, enquanto 二 tem outros usos em números.", "phrase": "我有两本书。", "reading": "Wǒ yǒu liǎng běn shū.", "meaning": "Tenho dois livros.", "wrong": "我有两本书 significa tenho vinte livros.", "task": "Escreva quantidades fictícias de livros e pessoas usando classificadores adequados."}, {"id": "course-chines-6", "title": "Posse, família e existência", "module": "1 · Básico", "language": true, "stage": 0, "theory": "的 liga possuidor e elemento possuído em muitos contextos, mas pode ser omitido em algumas relações próximas. 有 expressa ter ou existência conforme a construção. Sua negação usual é 没有, e não 不有. Identifique quem possui e o que está sendo apresentado.", "phrase": "这是我的书。", "reading": "Zhè shì wǒ de shū.", "meaning": "Este é o meu livro.", "wrong": "这是我的书 significa este é o seu livro, necessariamente.", "task": "Descreva dois objetos e seus donos fictícios, usando 的."}, {"id": "course-chines-7", "title": "Tempo e rotina", "module": "1 · Básico", "language": true, "stage": 0, "theory": "Expressões de tempo costumam vir antes do verbo, frequentemente antes ou depois do sujeito. Verbos não se conjugam por pessoa como em português. 每天 indica todos os dias; 明天 e 昨天 ajudam a localizar a situação no tempo. O contexto e os marcadores são essenciais.", "phrase": "我每天学习中文。", "reading": "Wǒ měitiān xuéxí Zhōngwén.", "meaning": "Estudo chinês todos os dias.", "wrong": "我每天学习中文 significa estudei chinês apenas uma vez ontem.", "task": "Descreva uma rotina fictícia com duas ações e uma expressão de tempo."}, {"id": "course-chines-8", "title": "Localização, pedidos e comida", "module": "1 · Básico", "language": true, "stage": 0, "theory": "在 pode indicar localização. Em 在学校学习, o lugar aparece antes do verbo da ação. 请 ajuda a formular pedidos e 谢谢 agradece. Aprenda vocabulário de situações práticas em frases e confirme quantidades antes de finalizar um pedido.", "phrase": "请给我一杯水。", "reading": "Qǐng gěi wǒ yì bēi shuǐ.", "meaning": "Dê-me um copo de água, por favor.", "wrong": "请给我一杯水 significa não me dê água.", "task": "Crie um pedido cortês e diga onde uma pessoa fictícia está."}, {"id": "course-chines-9", "title": "Negação e contrastes de aspecto", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "不 é frequente na negação de hábitos, intenções e estados; 没 ou 没有 nega muitas ocorrências de eventos. A escolha não corresponde simplesmente a presente e passado. Compare 我不去, que pode indicar não ir, com 我没去, que nega uma ida ocorrida no contexto.", "phrase": "我昨天没去学校。", "reading": "Wǒ zuótiān méi qù xuéxiào.", "meaning": "Não fui à escola ontem.", "wrong": "我昨天没去学校 significa fui à escola ontem.", "task": "Contraste um hábito que uma personagem não tem com um evento que ela não realizou."}, {"id": "course-chines-10", "title": "了: conclusão e mudança", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "了 não é uma terminação universal de passado. Pode marcar aspecto perfectivo depois do verbo ou mudança de situação ao final, com funções relacionadas mas distintas. Tempo continua dependendo do contexto; evite acrescentar 了 mecanicamente a toda frase passada.", "phrase": "我买了一本书。", "reading": "Wǒ mǎi le yì běn shū.", "meaning": "Comprei um livro.", "wrong": "我买了一本书 significa vou comprar um livro e ainda não comprei, necessariamente.", "task": "Descreva uma compra fictícia concluída e explique por que 了 não é conjugação de passado."}, {"id": "course-chines-11", "title": "Experiência com 过", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "过 depois do verbo pode apresentar experiência de ter realizado algo. Compare com um evento específico usando contexto e outros marcadores. Para negar experiência, 没有 mais verbo e 过 é um padrão frequente. A forma não muda por pessoa.", "phrase": "我去过北京。", "reading": "Wǒ qù guo Běijīng.", "meaning": "Já fui a Pequim.", "wrong": "我去过北京 significa nunca fui a Pequim.", "task": "Relate uma experiência fictícia e negue outra usando 没有 e 过."}, {"id": "course-chines-12", "title": "Ação em curso e duração", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "在 e 正在 antes do verbo podem apresentar ação em andamento. 着 tem outros usos aspectuais, incluindo estados e situações contínuas; não substitui 在 em qualquer frase. Duração pode exigir uma organização específica da frase e deve ser estudada com exemplos completos.", "phrase": "她正在看书。", "reading": "Tā zhèngzài kàn shū.", "meaning": "Ela está lendo um livro.", "wrong": "她正在看书 significa ela nunca lê livros.", "task": "Descreva duas ações acontecendo agora e identifique o verbo de cada uma."}, {"id": "course-chines-13", "title": "Comparação com 比", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Na construção A 比 B mais adjetivo, A é comparado a B. Não use automaticamente 很 antes do adjetivo nesse padrão. Uma diferença específica pode vir depois, como 三岁 para três anos em comparação de idade. Há outras construções para igualdade e comparação negativa.", "phrase": "今天比昨天冷。", "reading": "Jīntiān bǐ zuótiān lěng.", "meaning": "Hoje está mais frio que ontem.", "wrong": "今天比昨天冷 significa ontem está mais frio que hoje.", "task": "Compare dois dias ou objetos fictícios com 比 e confira a direção da comparação."}, {"id": "course-chines-14", "title": "Modais: 会, 能 e 可以", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "会 pode indicar habilidade aprendida ou probabilidade; 能 costuma envolver capacidade ou condições; 可以 frequentemente expressa permissão ou possibilidade. Seus usos se sobrepõem parcialmente e dependem do contexto. Não os trate como traduções sempre intercambiáveis de poder.", "phrase": "我会说中文。", "reading": "Wǒ huì shuō Zhōngwén.", "meaning": "Sei falar chinês.", "wrong": "我会说中文 significa tenho proibição de falar chinês.", "task": "Escreva uma habilidade e um pedido de permissão fictícios com modais adequados."}, {"id": "course-chines-15", "title": "Complementos de resultado", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "Um complemento após o verbo pode indicar o resultado alcançado: 看懂 é ler ou ver e entender; 写完 é terminar de escrever. Entender a ação e seu resultado como unidades ajuda a evitar traduções palavra por palavra. A negação depende de o resultado ter ocorrido ou ser possível.", "phrase": "我看懂了这篇文章。", "reading": "Wǒ kàndǒng le zhè piān wénzhāng.", "meaning": "Consegui entender este texto ao lê-lo.", "wrong": "我看懂了这篇文章 significa li o texto sem entender nada.", "task": "Use um composto de ação e resultado para relatar uma atividade fictícia concluída."}, {"id": "course-chines-16", "title": "Sequência, causa e condição", "module": "2 · Intermediário", "language": true, "stage": 1, "theory": "先 e 再 organizam primeiro e depois. 因为 e 所以 podem ligar causa e resultado. 如果 e 就 ajudam a formular condições. A posição dos participantes continua importante; conectivos não substituem a necessidade de uma frase com sentido completo.", "phrase": "因为下雨，所以我不出去。", "reading": "Yīnwèi xià yǔ, suǒyǐ wǒ bù chūqù.", "meaning": "Como está chovendo, não saio.", "wrong": "因为下雨，所以我不出去 significa saio porque não chove.", "task": "Crie uma sequência de estudo e uma condição com resultado."}, {"id": "course-chines-17", "title": "Construção com 把", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "把 coloca um objeto conhecido antes do verbo e destaca o que acontece com ele. Em usos típicos, o predicado precisa mostrar um efeito, resultado, destino ou outra informação além de um verbo isolado. Não anteponha 把 a qualquer objeto sem considerar essas condições.", "phrase": "我把作业写完了。", "reading": "Wǒ bǎ zuòyè xiěwán le.", "meaning": "Terminei de fazer a tarefa.", "wrong": "我把作业写完了 significa ainda não comecei a tarefa.", "task": "Identifique objeto e resultado na frase e crie outro exemplo simples com 写完."}, {"id": "course-chines-18", "title": "Passiva com 被", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "被 organiza a frase a partir do participante afetado. O agente pode aparecer depois de 被, conforme a construção. A frase precisa ser adequada ao contexto e ao evento, e não uma transposição automática de toda passiva portuguesa. Muitas passivas descrevem consequências relevantes.", "phrase": "我的自行车被偷了。", "reading": "Wǒ de zìxíngchē bèi tōu le.", "meaning": "Minha bicicleta foi roubada.", "wrong": "我的自行车被偷了 significa roubei uma bicicleta de outra pessoa.", "task": "Compare agente e afetado numa ação ativa e numa passiva fictícia."}, {"id": "course-chines-19", "title": "Complementos potenciais e grau", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Em 看得懂 e 看不懂, 得 ou 不 separam ação e resultado para expressar possibilidade ou impossibilidade de entender. O uso de 得 para grau ou maneira tem outra organização, como 说得很好. Diferencie função e padrão em vez de atribuir uma única tradução a 得.", "phrase": "这本书我看得懂。", "reading": "Zhè běn shū wǒ kàndedǒng.", "meaning": "Consigo entender este livro ao lê-lo.", "wrong": "这本书我看得懂 significa sou incapaz de entender este livro.", "task": "Contraste poder e não poder compreender um texto, e descreva a maneira de falar de uma personagem."}, {"id": "course-chines-20", "title": "Relativas e estrutura de tópico", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Modificadores com 的 podem vir antes do substantivo: 我昨天买的书. Em organização de tópico e comentário, um elemento conhecido pode aparecer primeiro e ser retomado pelo restante da frase. Analise a relação com o contexto antes de concluir que a ordem está errada.", "phrase": "这是我昨天买的书。", "reading": "Zhè shì wǒ zuótiān mǎi de shū.", "meaning": "Este é o livro que comprei ontem.", "wrong": "这是我昨天买的书 significa este é o livro que comprarei amanhã.", "task": "Descreva um objeto por uma ação anterior ao nome e destaque o tópico da frase."}, {"id": "course-chines-21", "title": "Ênfase com 是…的", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "A construção 是…的 pode destacar circunstâncias como tempo, lugar e modo de um evento já tomado como ocorrido. Ela não substitui 了 em toda referência ao passado. Identifique a informação em foco e o que o interlocutor já sabe sobre o acontecimento.", "phrase": "我是昨天来的。", "reading": "Wǒ shì zuótiān lái de.", "meaning": "Foi ontem que eu vim.", "wrong": "我是昨天来的 significa virei amanhã, em um plano ainda não realizado.", "task": "Reescreva um evento fictício dando ênfase a quando ele aconteceu."}, {"id": "course-chines-22", "title": "Concessão e argumentação", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "虽然 e 但是 frequentemente relacionam concessão e contraste. 不仅…而且 amplia informação: não só, mas também. Um argumento precisa de evidência e limites; o conectivo deve indicar a relação real entre as ideias, não apenas tornar o texto longo.", "phrase": "虽然很难，但是我想继续学习。", "reading": "Suīrán hěn nán, dànshì wǒ xiǎng jìxù xuéxí.", "meaning": "Embora seja difícil, quero continuar estudando.", "wrong": "虽然很难，但是我想继续学习 significa é fácil, por isso abandonei o estudo.", "task": "Escreva um argumento de três frases com uma dificuldade e uma decisão."}, {"id": "course-chines-23", "title": "Registro formal e leitura crítica", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Vocabulário formal como 因此 e 然而 exige relações claras de consequência e contraste. Em leitura, localize opinião, evidência e referência dos pronomes. A ausência de conjugação verbal não elimina distinções de tempo e aspecto, que dependem de contexto e marcadores.", "phrase": "这个方法有优点，然而也有局限。", "reading": "Zhège fāngfǎ yǒu yōudiǎn, rán'ér yě yǒu júxiàn.", "meaning": "Este método tem vantagens; no entanto, também tem limitações.", "wrong": "这个方法有优点，然而也有局限 significa que o método só tem vantagens.", "task": "Resuma uma proposta fictícia em três frases: benefício, limitação e conclusão."}, {"id": "course-chines-24", "title": "Produção avançada e revisão", "module": "3 · Avançado", "language": true, "stage": 2, "theory": "Planeje um texto por propósito, público e sequência de ideias. Confira posição do tempo e do lugar, classificadores, aspecto e relação entre orações. Escreva caracteres que consegue explicar e consulte pinyin apenas como apoio. A revisão deve avaliar sentido e não só aparência.", "phrase": "总的来说，我们需要根据实际情况作出决定。", "reading": "Zǒng de lái shuō, wǒmen xūyào gēnjù shíjì qíngkuàng zuòchū juédìng.", "meaning": "Em termos gerais, precisamos decidir com base na situação real.", "wrong": "总的来说，我们需要根据实际情况作出决定 significa devemos ignorar a situação real ao decidir.", "task": "Produza de cinco a oito frases sobre uma forma de estudar, com motivo, contraponto e conclusão; revise com uma referência."}]}];
STUDY_COURSES.push(...LANGUAGE_COURSES);
